"use client";

import { FormEvent, ReactNode, useCallback, useEffect, useRef, useState } from "react";
import { categories, states, relationships, outcomeLabels, level, type User, type Question, type Answer, type Snapshot, type View } from "./lib/community-model";
import { AccountRecovery, AccountSecurity, Challenge } from "./account-controls";
import RewardsPanel from "./rewards-panel";
import KnowledgeFields from "./knowledge-fields";
type Act = (body: Record<string, unknown>) => Promise<Record<string, unknown> | null>;
type Upload = (file: File) => Promise<string>;
const ago=(date:string)=>new Intl.DateTimeFormat("en-AU",{day:"numeric",month:"short",year:"numeric",timeZone:"Australia/Sydney"}).format(new Date(date.includes("T")?date:`${date.replace(" ","T")}Z`));
const authHref=()=>`/auth?returnTo=${encodeURIComponent(window.location.pathname+window.location.search)}`;
const values=(form:FormData)=>Object.fromEntries([...form.entries()].filter(([,value])=>typeof value==="string"));
const Icon=({children}:{children:string})=><span className="icon" aria-hidden="true">{children}</span>;
function Avatar({user}:{user:User}) { return <span className={`avatar avatar-${user.id}`}>{user.avatar_url?<img src={user.avatar_url} alt=""/>:user.initials}</span>; }
function UserBadge({user,compact=false}:{user?:User;compact?:boolean}) {
  if(!user) return null;
  return <a className={`user-badge ${compact?"compact":""}`} href={`/people/${user.handle}`}><Avatar user={user}/><span><strong>{user.name} {Boolean(user.verified)&&<span className="verified" title={`Verified in ${user.verified_scope}`}>✓</span>}</strong><small>{user.role} · {user.town}, {user.state}{Boolean(user.demo)&&" · Demo profile"}</small></span></a>;
}
function ProductNote({answer}:{answer:Pick<Answer,"product_name"|"commercial"|"relationship">}) {
  if(!answer.product_name&&!answer.commercial) return null;
  return <div className={answer.commercial?"disclosure":"product-note"}>{answer.product_name&&<strong>{answer.product_name} · </strong>}{(Object.hasOwn(relationships,answer.relationship)?relationships[answer.relationship]:null) || (answer.commercial?"Commercial relationship":"Product mentioned")}{Boolean(answer.commercial)&&" · Commercial disclosure"}</div>;
}
function Form({children,submit,className="editor-card",reset=false,onInput}:{children:ReactNode;submit:(data:FormData,form:HTMLFormElement)=>Promise<boolean>;className?:string;reset?:boolean;onInput?:(form:HTMLFormElement)=>void}) {
  const [busy,setBusy]=useState(false),[error,setError]=useState("");
  async function send(event:FormEvent<HTMLFormElement>) { event.preventDefault(); if(busy) return; const form=event.currentTarget; const data=new FormData(form); setBusy(true);setError(""); try {if(await submit(data,form) && reset) form.reset();}catch(cause){setError(cause instanceof Error?cause.message:"Could not save. Your input has been kept.");}finally{setBusy(false);} }
  return <form className={className} onSubmit={send} onInput={event=>onInput?.(event.currentTarget)}><fieldset disabled={busy}>{children}{error&&<p role="alert" className="form-error">{error}</p>}{busy&&<p role="status">Saving…</p>}</fieldset></form>;
}
function Select({label,name,items,value,onChange,empty="All"}:{label:string;name:string;items:string[];value?:string;onChange?:(value:string)=>void;empty?:string}) {
  return <label>{label}<select name={name} value={value} onChange={e=>onChange?.(e.target.value)}><option value="">{empty}</option>{items.map(item=><option key={item}>{item}</option>)}</select></label>;
}
function Header({data}:{data:Snapshot|null}) {
  const current=data?.users.find(u=>u.id===data.currentUserId), unread=data?.notifications.filter(n=>!n.read_at).length || 0;
  return <><header className="site-header"><a className="brand" href="/" aria-label="Grounded Australia home"><span className="brand-mark">G</span><span>Grounded<small>Australia</small></span></a><nav aria-label="Main navigation"><a href="/">Community</a><a href="/search?type=knowledge">Knowledge</a><a href="/search?type=experts">Find experts</a><a href="/leaderboard">Contributors</a><a href="/rewards">Rewards</a></nav><div className="header-actions"><a className="search-link" href="/search" aria-label="Search">⌕</a>{current?<><a className="inbox-link" href="/me?tab=notifications">Inbox {unread>0&&<b>{unread}</b>}</a><a className="mini-avatar" href="/me" aria-label="My community">{current.initials}</a></>:<a className="auth-link" href="/auth">Sign in</a>}<a className="button primary small" href="/ask">Ask a question</a></div></header><nav className="mobile-nav" aria-label="Mobile navigation"><a href="/">Questions</a><a href="/search?type=experts">Experts</a><a href="/ask">＋ Ask</a><a href="/rewards">Rewards</a><a href="/me">Account{unread>0?` (${unread})`:""}</a></nav></>;
}
function Empty({children}:{children:ReactNode}) {return <div className="empty">{children}</div>;}
function Pager({data,setParam}:{data:Snapshot;setParam:(key:string,value:string)=>void}) {return data.pages>1?<nav className="pagination" aria-label="Results pages"><button disabled={data.page<=1} onClick={()=>setParam("page",String(data.page-1))}>Previous</button><span>Page {data.page} of {data.pages}</span><button disabled={data.page>=data.pages} onClick={()=>setParam("page",String(data.page+1))}>Next</button></nav>:null;}
function QuestionCard({question:q,data}:{question:Question;data:Snapshot}) {
  const answers=data.answers.filter(a=>a.question_id===q.id),selected=answers.find(a=>a.id===q.selected_answer_id),best=selected || [...answers].sort((a,b)=>b.score-a.score)[0];
  return <article className={`question-card ${q.context.kind==="knowledge"?"knowledge-card ":""}${q.image_url?"has-image":"no-image"}`}>{q.image_url&&<a className="question-image" href={`/questions/${q.slug}`}><img src={q.image_url} alt={q.context.kind==="knowledge"?`Image for ${q.title}`:"Photo supplied with this field question"} loading="lazy"/></a>}<div className="question-copy"><div className="eyebrow-row"><span className="category-pill">{q.context.kind==="knowledge"?"Knowledge sharing":q.category}</span><span>{q.town}, {q.state}</span><span>{ago(q.created_at)}</span>{Boolean(q.demo)&&<span className="demo-label">Demo question</span>}</div><h2><a href={`/questions/${q.slug}`}>{q.title}</a></h2><p>{q.body}</p><div className="tag-row">{q.tags.map(tag=><a key={tag} href={`/search?q=${encodeURIComponent(tag)}`}>#{tag}</a>)}</div>{best&&<div className="answer-preview"><div><strong>{selected?"Author accepted":"Community answer"} · {data.users.find(u=>u.id===best.author_id)?.name}</strong><p>{best.body}</p><ProductNote answer={best}/></div></div>}<div className="status-row"><span>{q.answer_count} {q.answer_count===1?"answer":"answers"}</span>{q.outcome!=="not_reported"&&<span>{outcomeLabels[q.outcome]}</span>}</div><div className="card-footer"><UserBadge user={data.users.find(u=>u.id===q.author_id)} compact/><div><span>{q.views} views</span><span>{q.follow_count} following</span></div></div></div></article>;
}
function Feed({data,params,setParam,search=false}:{data:Snapshot;params:URLSearchParams;setParam:(key:string,value:string)=>void;search?:boolean}) {
  const type=params.get("type") || "questions";
  const content=type==="questions" || type==="knowledge";
  const people=data.users.filter(u=>data.peopleIds.includes(u.id));
  const current=data.users.find(u=>u.id===data.currentUserId);
  return <><section className="community-intro"><div><span className="kicker">Australian agriculture</span><h1>{search?"Find field knowledge.":"Find answers for your patch."}</h1><p>{search?"Search by crop, concern, town or professional field.":"Practical questions, local experience and results from the field."}</p></div><form action="/search" className="home-search"><label htmlFor="search-query">Search questions and people</label><div><input key={params.get("q")} id="search-query" name="q" defaultValue={params.get("q")||""} placeholder="Try wheat, calf scours or Horsham"/><input type="hidden" name="type" value={type}/>{["state","category","status","sort"].map(key=><input key={key} type="hidden" name={key} value={params.get(key)||""}/>)}<button className="button primary">Search</button></div></form></section><section className="workspace-layout"><aside className="filter-panel"><h2>Find your field</h2>{search&&<label>Search for<select value={type} onChange={e=>setParam("type",e.target.value)}><option value="questions">Community posts</option><option value="knowledge">Knowledge sharing</option><option value="experts">Verified experts</option><option value="people">All people</option></select></label>}<Select label="Category" name="category" items={categories} value={params.get("category")||""} onChange={v=>setParam("category",v)}/><Select label="State or service region" name="state" items={states} value={params.get("state")||""} onChange={v=>setParam("state",v)}/>{current&&<button className="text-link" onClick={()=>setParam("state",current.state)}>Use my state: {current.state}</button>}{content&&<><label>Answer status<select value={params.get("status")||""} onChange={e=>setParam("status",e.target.value)}><option value="">Any status</option><option value="unanswered">Unanswered</option><option value="expert">Verified expert answered</option></select></label><label>Sort questions<select value={params.get("sort")||"latest"} onChange={e=>setParam("sort",e.target.value)}><option value="latest">Latest</option><option value="answered">Most answered</option><option value="popular">Most viewed</option></select></label></>}<a className="text-link" href={search?`/search?type=${type}`:"/"}>Clear filters</a></aside><div className="feed"><div className="section-heading"><h2>{content?`${data.total} ${type==="knowledge"?"knowledge posts":"community posts"}`:type==="experts"?"Verified experts":"Community members"}</h2>{content&&(type==="knowledge"?data.isModerator&&<a className="button primary" href="/ask?type=knowledge">Publish knowledge</a>:<a className="button primary" href="/ask">Ask a question</a>)}</div>{content?<>{data.questions.map(q=><QuestionCard key={q.id} question={q} data={data}/>)}{!data.questions.length&&<Empty><h3>{type==="knowledge"?"No knowledge posts yet":"No questions match yet"}</h3><p>{type==="knowledge"?"Practical guides will appear here once published.":"Try another region or share your own field question."}</p></Empty>}<Pager data={data} setParam={setParam}/></>:<><div className="people-directory">{people.map(user=><a className="person-card" key={user.id} href={`/people/${user.handle}`}><Avatar user={user}/><h3>{user.name} {Boolean(user.verified)&&"✓"}</h3><p>{user.specialties || user.role}</p><p>{user.town}, {user.state}</p><small>{user.verified?`Verified in ${user.verified_scope}`:level(user.xp)}{user.demo?" · Demo profile":""}</small><p>Service regions: {user.service_states.join(", ") || user.state}</p></a>)}</div>{!people.length&&<Empty><h3>No matching {type==="experts"?"verified experts":"members"} yet</h3><p>Broaden your filters. Expert badges are awarded after review.</p></Empty>}<Pager data={data} setParam={setParam}/></>}</div></section></>;
}
function QuestionEditor({data,act,upload,question,onCancel,knowledge=false}:{data:Snapshot;act:Act;upload:Upload;question?:Question;onCancel?:()=>void;knowledge?:boolean}) {
  const current=data.users.find(u=>u.id===data.currentUserId);
  knowledge=knowledge || question?.context.kind==="knowledge";
  const draftKey=knowledge?"grounded-knowledge-draft":"grounded-question-draft";
  const [category,setCategory]=useState(question?.category||"Crops"),[draft,setDraft]=useState<Record<string,string>|null>(null);
  const [formVersion,setFormVersion]=useState(0);const key=useRef("");
  const [draftStatus,setDraftStatus]=useState("Not published");
  useEffect(()=>{if(!question){try{const saved=JSON.parse(localStorage.getItem(draftKey)||"null");if(saved){setDraft(saved);setCategory(saved.category||"Crops");setFormVersion(1);setDraftStatus("Draft restored from this device");}}catch{}}},[question,draftKey]);
  const ctx=question?.context || {};
  if(knowledge && !data.isModerator)return <Empty><h1>Administrator access required</h1><a href="/auth?returnTo=%2Fask%3Ftype%3Dknowledge">Sign in as administrator</a></Empty>;
  const saveDraft=(form:HTMLFormElement)=>{if(!question){try{localStorage.setItem(draftKey,JSON.stringify(values(new FormData(form))));setDraftStatus("Draft saved on this device");}catch{setDraftStatus("Draft could not be saved on this device");}}};
  const submit=async (form:FormData)=>{
    if(!current){window.location.href=authHref();return false;} key.current ||= crypto.randomUUID();
    const file=form.get("image"); const imageUrl=file instanceof File&&file.size?await upload(file):form.get("removeImage")==="on"?null:undefined;
    const context=Object.fromEntries(["subject","stage","started","extent","conditions","tried",...(knowledge?["imageCaption"]:[])].map(field=>[field,form.get(field)]));
    const result=await act({...values(form),action:question?"editQuestion":"ask",questionId:question?.id,kind:knowledge?"knowledge":"question",context,imageUrl,requestKey:key.current});
    if(result){try{localStorage.removeItem(draftKey);}catch{}window.location.href=`/questions/${result.slug}`;return true;}return false;
  };
  if(knowledge)return <section className="knowledge-editor">
    <a className="knowledge-back" href="/me">← My community</a>
    <header className="knowledge-heading"><div><span className="kicker">Admin / Knowledge sharing</span><h1>{question?"Edit your article":"Create an article"}</h1><p>Practical knowledge, ready to share.</p></div><div className="knowledge-draft-status" role="status"><span aria-hidden="true">{question?"◉":"○"}</span>{question?"Editing a published article":draftStatus}</div></header>
    {onCancel&&<button className="knowledge-cancel" type="button" onClick={onCancel}>← Back to article</button>}
    <Form className="knowledge-form" key={formVersion} onInput={saveDraft} submit={submit}><KnowledgeFields question={question} current={current} draft={draft} category={category} setCategory={setCategory} uploadsEnabled={data.config.uploadsEnabled}/></Form>
  </section>;
  return <section className="editor-page"><div className="section-heading"><div><span className="kicker">{knowledge?"Knowledge sharing":question?"Edit question":"Ask the community"}</span><h1>{knowledge?question?"Edit knowledge sharing":"Share practical knowledge":question?"Update the field picture":"What are you seeing?"}</h1><p>{knowledge?"Share practical guidance, its sources and where it applies.":"Share enough context for someone with relevant experience to help."}</p></div>{onCancel&&<button onClick={onCancel}>Cancel</button>}</div><Form key={formVersion} onInput={form=>{if(!question)localStorage.setItem(draftKey,JSON.stringify(values(new FormData(form))));}} submit={submit}><label>{knowledge?"Article title":"Question title"}<input name="title" required minLength={12} maxLength={160} defaultValue={question?.title||draft?.title||""} placeholder="What changed, and what do you need to understand?"/></label><div className="two-col"><label>Category<select name="category" value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label>Tags<input name="tags" defaultValue={question?.tags.join(", ")||draft?.tags||""} placeholder="wheat, nitrogen, waterlogging" maxLength={180}/></label></div><div className="two-col"><label>State or territory<select name="state" required defaultValue={question?.state||draft?.state||current?.state||""}><option value="">Choose a state</option>{states.map(s=><option key={s}>{s}</option>)}</select></label><label>Nearest town<input name="town" required maxLength={80} defaultValue={question?.town||draft?.town||current?.town||""}/><small>Public town or region only. Do not include your farm address.</small></label></div><details className="context-fields" open={!knowledge}><summary>Field context <span>Optional · leave unknown details blank</span></summary><div className="two-col"><label>{category==="Livestock"?"Animal and breed":"Crop, variety or system"}<input name="subject" maxLength={500} defaultValue={ctx.subject||draft?.subject||""}/></label><label>{category==="Livestock"?"Age / production stage":"Growth stage"}<input name="stage" maxLength={500} defaultValue={ctx.stage||draft?.stage||""}/></label><label>When did it start?<input name="started" maxLength={500} defaultValue={ctx.started||draft?.started||""}/></label><label>Affected area / number of animals<input name="extent" maxLength={500} defaultValue={ctx.extent||draft?.extent||""}/></label></div><label>Recent weather, soil or housing conditions<input name="conditions" maxLength={500} defaultValue={ctx.conditions||draft?.conditions||""}/></label><label>What have you tried?<input name="tried" maxLength={500} defaultValue={ctx.tried||draft?.tried||""}/></label></details><label>{knowledge?"Knowledge and practical guidance":"Full field detail"}<textarea name="body" rows={6} required minLength={30} maxLength={5000} defaultValue={question?.body||draft?.body||""} placeholder={knowledge?"Share your guidance, evidence, sources and limitations.":"Describe the symptoms, changes and the help you need."}/></label><div className="two-col">{data.config.uploadsEnabled?<label>Photo · JPEG, PNG or WebP, max 5 MB<input name="image" type="file" accept="image/jpeg,image/png,image/webp"/></label>:<p>Photo uploads are not enabled yet. Describe what you see in the field.</p>}<label>Video link · optional<input name="videoUrl" type="url" defaultValue={question?.video_url||draft?.videoUrl||""} placeholder="https://…"/></label></div>{question?.image_url&&<label className="check-label"><input type="checkbox" name="removeImage"/>Remove current photo</label>}<div className="form-submit"><small>{current?"Your post will be public.":data.config.uploadsEnabled?"Your text draft is saved on this device. Photos must be selected again after signing in.":"Your text draft is saved on this device."}</small><button className="button primary">{current?question?"Save changes":knowledge?"Publish knowledge":"Publish question":"Sign in to publish"}</button></div></Form></section>;
}
function ReportControl({type,id,act}:{type:string;id:number;act:Act}) {
  const [open,setOpen]=useState(false);
  return <><button className="text-link" onClick={()=>setOpen(!open)}>{open?"Cancel report":"Report"}</button>{open&&<Form className="inline-form" submit={async form=>{const result=await act({action:"report",targetType:type,targetId:id,reason:form.get("reason")});if(result)setOpen(false);return Boolean(result);}}><label>What should the moderators review?<textarea name="reason" required minLength={4} maxLength={300} rows={3}/></label><button className="button outline">Send report</button></Form>}</>;
}
function AnswerEditor({answer,questionId,data,act,upload,onDone}:{answer?:Answer;questionId:number;data:Snapshot;act:Act;upload:Upload;onDone?:()=>void}) {
  const key=useRef("");
  return <Form className="answer-editor" reset={!answer} submit={async form=>{key.current ||= crypto.randomUUID();const file=form.get("image");const imageUrl=file instanceof File&&file.size?await upload(file):form.get("removeImage")==="on"?null:undefined;const result=await act({...values(form),action:answer?"editAnswer":"answer",answerId:answer?.id,questionId,imageUrl,requestKey:key.current});if(result){key.current="";onDone?.();}return Boolean(result);}}><h3>{answer?"Edit your answer":"Write an answer"}</h3><label>Practical answer<textarea name="body" required minLength={20} maxLength={5000} rows={6} defaultValue={answer?.body||""} placeholder="Explain what you would check, the conditions where this applies and your experience."/></label><div className="two-col"><label>Supporting reference<input name="citationUrl" type="url" defaultValue={answer?.citation_url||""} placeholder="https://…"/></label><label>Video link<input name="videoUrl" type="url" defaultValue={answer?.video_url||""} placeholder="https://…"/></label></div>{data.config.uploadsEnabled?<label>Photo · JPEG, PNG or WebP, max 5 MB<input name="image" type="file" accept="image/jpeg,image/png,image/webp"/></label>:<p>Photo uploads are not enabled yet. Describe what you see in the field.</p>}{answer?.image_url&&<label className="check-label"><input type="checkbox" name="removeImage"/>Remove current photo</label>}<div className="two-col"><label>Product or partner name<input name="productName" maxLength={100} defaultValue={answer?.product_name||""}/></label><label>Your relationship<select name="relationship" defaultValue={answer?.relationship||"none"}>{Object.entries(relationships).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label></div><small>Disclose free samples, paid partnerships and employment. The label appears wherever your answer is previewed.</small><div className="form-actions"><button className="button primary">{answer?"Save revision":"Publish answer"}</button>{answer&&<button type="button" onClick={onDone}>Cancel</button>}</div></Form>;
}
function discussionPage(key:string,value:number,answerId?:number) {
  const params=new URLSearchParams(window.location.search);params.delete("answer");params.set(key,String(value));
  if(answerId) {params.set("commentAnswer",String(answerId));params.set("answer",String(answerId));}
  window.location.href=`${window.location.pathname}?${params}#${answerId?`answer-${answerId}`:"answers"}`;
}
function AnswerCard({answer,question,data,act,upload}:{answer:Answer;question:Question;data:Snapshot;act:Act;upload:Upload}) {
  const [editing,setEditing]=useState(false),[deleting,setDeleting]=useState(false);const key=useRef("");
  const mine=answer.author_id===data.currentUserId,selected=question.selected_answer_id===answer.id,ownVote=data.votes.find(v=>v.answer_id===answer.id)?.value||0;
  const comments=data.comments.filter(c=>c.answer_id===answer.id),revisions=data.revisions.filter(r=>r.answer_id===answer.id);
  return <article id={`answer-${answer.id}`} className={`answer-card ${selected?"selected":""}`}>{selected&&<div className="selected-ribbon">✓ Accepted by the question author</div>}<div className="answer-layout"><div className="vote-box"><button aria-label="Upvote answer" disabled={mine} aria-pressed={ownVote===1} onClick={()=>act({action:"vote",answerId:answer.id,value:ownVote===1?0:1})}>▲</button><strong>{answer.score}</strong><button aria-label="Downvote answer" disabled={mine} aria-pressed={ownVote===-1} onClick={()=>act({action:"vote",answerId:answer.id,value:ownVote===-1?0:-1})}>▼</button></div><div className="answer-main"><div className="answer-author"><UserBadge user={data.users.find(u=>u.id===answer.author_id)}/><small>{ago(answer.created_at)}{answer.updated_at?` · Edited ${ago(answer.updated_at)}`:""}</small></div><ProductNote answer={answer}/>{editing?<AnswerEditor data={data} answer={answer} questionId={question.id} act={act} upload={upload} onDone={()=>setEditing(false)}/>:<><p className="answer-body">{answer.body}</p>{answer.image_url&&<img className="answer-image" src={answer.image_url} alt="Photo supplied with this answer" loading="lazy"/>}{answer.citation_url&&<a className="reference-link" href={answer.citation_url} target="_blank" rel="noreferrer">View supporting reference ↗</a>}{answer.video_url&&<a className="reference-link" href={answer.video_url} target="_blank" rel="noreferrer">Watch field video ↗</a>}</>}<div className="answer-actions">{question.author_id===data.currentUserId&&!selected&&<button onClick={()=>act({action:"selectBest",questionId:question.id,answerId:answer.id})}>Accept answer</button>}{mine&&<><button onClick={()=>setEditing(!editing)}>Edit</button><button onClick={()=>setDeleting(!deleting)}>Delete</button></>}<ReportControl type="answer" id={answer.id} act={act}/></div>{deleting&&<div className="confirm-panel"><p>Remove this answer and its comments from public view?</p><button className="button outline" onClick={()=>act({action:"deleteAnswer",answerId:answer.id})}>Confirm removal</button><button onClick={()=>setDeleting(false)}>Keep answer</button></div>}{revisions.length>0&&<details className="revisions"><summary>View {revisions.length} recent earlier {revisions.length===1?"version":"versions"}</summary>{revisions.map(r=><div key={r.id}><small>Replaced {ago(r.created_at)}</small><ProductNote answer={r.content}/><p>{r.content.body}</p>{r.content.citation_url&&<a href={r.content.citation_url} rel="noreferrer" target="_blank">Previous reference ↗</a>}</div>)}</details>}<div className="comments">{comments.map(c=><div className="comment" key={c.id}><strong>{data.users.find(u=>u.id===c.author_id)?.name}</strong><p>{c.body}</p><small>{ago(c.created_at)}</small><ReportControl type="comment" id={c.id} act={act}/></div>)}</div>{answer.comment_count>20&&<nav className="pagination" aria-label="Comment pages"><button disabled={data.commentAnswer!==answer.id||data.commentPage<=1} onClick={()=>discussionPage("commentPage",data.commentPage-1,answer.id)}>Previous comments</button><span>{data.commentAnswer===answer.id?data.commentPage:1} / {Math.ceil(answer.comment_count/20)}</span><button disabled={(data.commentAnswer===answer.id?data.commentPage:1)*20>=answer.comment_count} onClick={()=>discussionPage("commentPage",(data.commentAnswer===answer.id?data.commentPage:1)+1,answer.id)}>Next comments</button></nav>}{data.currentUserId?<Form className="comment-form" reset submit={async form=>{key.current ||= crypto.randomUUID();const result=await act({action:"comment",answerId:answer.id,body:form.get("body"),requestKey:key.current});if(result)key.current="";return Boolean(result);}}><label>Add a follow-up comment<textarea name="body" rows={2} required minLength={2} maxLength={600}/></label><button className="button outline">Post comment</button></Form>:<a className="text-link" href="/auth">Sign in to comment</a>}</div></div></article>;
}
function QuestionPage({slug,data,act,upload}:{slug:string;data:Snapshot;act:Act;upload:Upload}) {
  const question=data.questions.find(q=>q.slug===slug);const [editing,setEditing]=useState(false),[shared,setShared]=useState("");
  useEffect(()=>{if(question&&!sessionStorage.getItem(`viewed-${question.id}`)){sessionStorage.setItem(`viewed-${question.id}`,"1");fetch("/api/community",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"view",questionId:question.id})}).catch(()=>{});}},[question]);
  if(!question)return <Empty><h1>Question unavailable</h1><p>It may have been removed or the link may have changed.</p><a href="/">Browse questions</a></Empty>;
  const q=question,answers=data.answers.filter(a=>a.question_id===q.id).sort((a,b)=>b.score-a.score),selected=answers.find(a=>a.id===q.selected_answer_id),top=answers.find(a=>a.id!==selected?.id);
  const previews=[selected,top].filter((a):a is Answer=>Boolean(a));
  const experts=data.users.filter(u=>u.verified&&!u.demo&&u.verified_scope===q.category&&u.id!==data.currentUserId).sort((a,b)=>Number(b.state===q.state||b.service_states.includes(q.state))-Number(a.state===q.state||a.service_states.includes(q.state)));
  if(editing)return <QuestionEditor data={data} act={act} upload={upload} question={q} onCancel={()=>setEditing(false)}/>;
  return <><section className="question-hero"><div className="breadcrumbs"><a href="/">Questions</a><span>›</span><a href={`/search?category=${q.category}`}>{q.category}</a><span>› {q.town}, {q.state}</span></div>{q.context.kind==="knowledge"&&<span className="kicker">Knowledge sharing</span>}<h1>{q.title}</h1><div className="status-row"><span>{ago(q.created_at)}</span><span>{q.answer_count} answers · {q.views} views</span><span>{outcomeLabels[q.outcome]}</span>{Boolean(q.demo)&&<span className="demo-label">Demo question · illustrative content</span>}</div><div className="field-facts">{Object.entries(q.context).filter(([key,v])=>!["kind","imageCaption"].includes(key)&&v).map(([key,value])=><span key={key}><strong>{({subject:"Subject",stage:"Stage",started:"Started",extent:"Affected",conditions:"Conditions",tried:"Already tried"} as Record<string,string>)[key]}:</strong> {value}</span>)}</div></section><section className="question-grid"><div>{previews.length>0&&<section className="quick-answers"><h2>Answers at a glance</h2>{previews.map(answer=><a key={answer.id} href={`?answer=${answer.id}#answer-${answer.id}`}><strong>{answer.id===selected?.id?"Author accepted":"Community reference"} · {data.users.find(u=>u.id===answer.author_id)?.name}</strong><p>{answer.body}</p><ProductNote answer={answer}/><small>Read the full answer and its context ↓</small></a>)}</section>}<article className="question-detail"><details open={q.context.kind==="knowledge"||!answers.length}><summary>{q.context.kind==="knowledge"?"Knowledge and practical guidance":"Full question and field background"}</summary><UserBadge user={data.users.find(u=>u.id===q.author_id)}/>{q.context.kind==="knowledge"&&q.image_url&&<figure className="knowledge-cover"><img src={q.image_url} alt={`Image for ${q.title}`}/>{q.context.imageCaption&&<figcaption>{q.context.imageCaption}</figcaption>}</figure>}<p className="answer-body">{q.body}</p>{q.context.kind!=="knowledge"&&q.image_url&&<img src={q.image_url} alt="Field photo supplied with the question"/>}{q.video_url&&<a href={q.video_url} className="reference-link" target="_blank" rel="noreferrer">Watch supplied field video ↗</a>}</details><div className="tag-row">{q.tags.map(tag=><a key={tag} href={`/search?q=${encodeURIComponent(tag)}`}>#{tag}</a>)}</div><div className="question-actions"><button aria-pressed={data.bookmarks.some(x=>x.question_id===q.id)} onClick={()=>act({action:"setBookmark",questionId:q.id,active:!data.bookmarks.some(x=>x.question_id===q.id)})}>{data.bookmarks.some(x=>x.question_id===q.id)?"★ Saved":"☆ Save"}</button><button aria-pressed={data.follows.some(x=>x.question_id===q.id)} onClick={()=>act({action:"setFollow",questionId:q.id,active:!data.follows.some(x=>x.question_id===q.id)})}>{data.follows.some(x=>x.question_id===q.id)?"Following updates":"Follow updates"}</button><button onClick={async()=>{try{await navigator.clipboard.writeText(window.location.href);setShared("Link copied");}catch{setShared(window.location.href);}}}>Share</button>{(data.currentUserId===q.author_id||data.isModerator)&&<button onClick={()=>setEditing(true)}>{q.context.kind==="knowledge"?"Edit knowledge":"Edit question"}</button>}<ReportControl type="question" id={q.id} act={act}/></div>{shared&&<p role="status">{shared}</p>}</article>{q.outcome_note&&<section className="outcome-card"><h2>Field follow-up: {outcomeLabels[q.outcome]}</h2><p>{q.outcome_note}</p><small>Reported by the question author {q.outcome_at&&ago(q.outcome_at)}. Conditions and results may differ elsewhere.</small></section>}{data.currentUserId===q.author_id&&<details className="outcome-editor"><summary>Record what happened in the field</summary><Form submit={async form=>Boolean(await act({action:"fieldOutcome",questionId:q.id,outcome:form.get("outcome"),note:form.get("note")}))}><label>Result<select name="outcome" defaultValue={q.outcome==="not_reported"?"trying":q.outcome}>{Object.entries(outcomeLabels).filter(([key])=>key!=="not_reported").map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>What did you try, and what changed?<textarea name="note" rows={4} required minLength={20} maxLength={2000} defaultValue={q.outcome_note}/></label><button className="button primary">Save field follow-up</button></Form></details>}<section id="answers" className="answer-section"><div className="section-heading"><h2>{q.answer_count} {q.answer_count===1?"answer":"answers"}</h2><small>Accepted answer first, then helpful votes</small></div>{answers.filter(a=>data.answerPageIds.includes(a.id)).map(answer=><AnswerCard key={answer.id} answer={answer} question={q} data={data} act={act} upload={upload}/>)}{!answers.length&&<Empty><h3>Local experience could help here</h3><p>Be the first to offer a practical answer.</p></Empty>}</section>{data.answerPages>1&&<nav className="pagination" aria-label="Answer pages"><button disabled={data.answerPage<=1} onClick={()=>discussionPage("answerPage",data.answerPage-1)}>Previous answers</button><span>{data.answerPage} / {data.answerPages}</span><button disabled={data.answerPage>=data.answerPages} onClick={()=>discussionPage("answerPage",data.answerPage+1)}>Next answers</button></nav>}{data.currentUserId?<AnswerEditor data={data} questionId={q.id} act={act} upload={upload}/>:<div className="sign-in-prompt"><a className="button primary" href={`/auth?returnTo=${encodeURIComponent(`/questions/${q.slug}`)}`}>Sign in to answer</a></div>}</div><aside className="question-aside"><div className="expert-card"><h2>Invite relevant expertise</h2><p>Verified in {q.category}. Experts serving {q.state} appear first.</p>{experts.slice(0,6).map(expert=>{const invited=data.invitations.some(i=>i.question_id===q.id&&i.inviter_id===data.currentUserId&&i.expert_id===expert.id);return <div className="expert-invite" key={expert.id}><UserBadge user={expert} compact/><small>{expert.state===q.state||expert.service_states.includes(q.state)?`Serves ${q.state}`:`Based in ${expert.state}`}</small><button disabled={invited} onClick={()=>act({action:"inviteExpert",questionId:q.id,expertId:expert.id})}>{invited?"Invited":"Invite"}</button></div>;})}{!experts.length&&<p>No verified expert in this field yet. Community members can still answer.</p>}<a className="text-link" href={`/search?type=experts&category=${q.category}`}>Browse this field</a></div><div className="safety-note"><p>For urgent animal health, chemical safety or biosecurity concerns, contact a local professional.</p></div></aside></section></>;
}
function ProfileEditor({user,data,act,upload}:{user:User;data:Snapshot;act:Act;upload:Upload}) {
  return <><Form submit={async (form,element)=>{const file=form.get("avatar");const avatarUrl=file instanceof File&&file.size?await upload(file):form.get("removeAvatar")==="on"?null:undefined;const result=await act({...values(form),action:"updateProfile",categories:form.getAll("categories"),serviceStates:form.getAll("serviceStates"),avatarUrl});if(result){const input=element.querySelector<HTMLInputElement>('input[name="avatar"]');if(input)input.value="";const remove=element.querySelector<HTMLInputElement>('input[name="removeAvatar"]');if(remove)remove.checked=false;}return Boolean(result);}}><h2>Your field profile</h2><div className="two-col"><label>Display name<input name="name" required minLength={2} maxLength={80} defaultValue={user.name}/></label><label>Agricultural role<select name="role" defaultValue={["Farmer","Agricultural professional","Enthusiast","Brand representative"].includes(user.role)?user.role:"Farmer"}>{["Farmer","Agricultural professional","Enthusiast","Brand representative"].map(role=><option key={role}>{role}</option>)}</select></label><label>State<select name="state" required defaultValue={user.state}>{states.map(state=><option key={state}>{state}</option>)}</select></label><label>Nearest town<input name="town" required maxLength={80} defaultValue={user.town}/></label></div><label>Bio<textarea name="bio" rows={4} maxLength={1500} defaultValue={user.bio}/></label><div className="two-col"><label>Specialties<input name="specialties" maxLength={300} defaultValue={user.specialties} placeholder="e.g. wheat, soil testing, dairy"/></label><label>Years of experience<input name="years" type="number" min={0} max={90} required defaultValue={user.years}/></label></div><div className="choice-group"><span>Fields you work in</span>{categories.map(category=><label className="check-label" key={category}><input type="checkbox" name="categories" value={category} defaultChecked={user.categories.includes(category)}/>{category}</label>)}</div><div className="choice-group"><span>Regions you can advise on</span>{states.map(state=><label className="check-label" key={state}><input type="checkbox" name="serviceStates" value={state} defaultChecked={user.service_states.includes(state)}/>{state}</label>)}</div>{data.config.uploadsEnabled&&<label>Profile photo · JPEG, PNG or WebP, max 5 MB<input name="avatar" type="file" accept="image/jpeg,image/png,image/webp"/></label>}{user.avatar_url&&<label className="check-label"><input type="checkbox" name="removeAvatar"/>Remove profile photo</label>}<button className="button primary">Save profile</button></Form><section className="verification-panel"><AccountSecurity data={data} act={act}/><h2>Expert verification</h2><p>Professional verification is reviewed separately from community XP. Only your verified field and the review basis are made public.</p>{data.application&&<div className="status-panel"><strong>Application: {data.application.status}</strong><p>{data.application.review_note || "Your application is awaiting a reviewer."}</p></div>}{user.verified?<p>Verified in {user.verified_scope}: {user.verification_basis}</p>:data.application?.status!=="pending"&&<Form className="inline-form" submit={async form=>Boolean(await act({action:"applyExpert",scope:form.get("scope"),evidence:form.get("evidence")}))}><label>Professional field<select name="scope" required>{categories.map(category=><option key={category}>{category}</option>)}</select></label><label>Organization, relevant experience and public credential / reference link<textarea name="evidence" required minLength={40} maxLength={3000} rows={5}/><small>Reviewers can see this information. Do not upload identity documents or private identifiers.</small></label><button className="button primary">Submit for review</button></Form>}</section></>;
}
function Profile({handle,data,act,setParam}:{handle:string;data:Snapshot;act:Act;setParam:(key:string,value:string)=>void}) {
  const user=data.users.find(u=>u.handle===handle);if(!user)return <Empty><h1>Profile not found</h1></Empty>;
  const own=user.id===data.currentUserId,following=data.userFollows.includes(user.id);
  return <><section className="profile-hero"><Avatar user={user}/><div><span className="kicker">{user.role} · {level(user.xp)}{user.demo?" · Demo profile":""}</span><h1>{user.name}</h1><p>@{user.handle} · {user.town}, {user.state}</p></div>{own?<a className="button cream" href="/me?tab=profile">Edit profile</a>:<button className="button cream" aria-pressed={following} onClick={()=>act({action:"followUser",userId:user.id,active:!following})}>{following?"Following":"Follow member"}</button>}</section><section className="profile-grid"><div><div className="profile-about"><h2>About</h2><p>{user.bio || "This member has not added a bio yet."}</p><p><strong>Specialties:</strong> {user.specialties || "Not provided"}</p><p><strong>Experience:</strong> {user.years} years · <strong>Regions:</strong> {user.service_states.join(", ")||user.state}</p>{Boolean(user.verified)&&<div className="verified-panel"><strong>✓ Verified in {user.verified_scope}</strong><p>{user.verification_basis}</p><small>{user.verified_at&&`Reviewed ${ago(user.verified_at)}`}</small></div>}</div><h2>Field activity</h2><p>Recent questions and answers. Open a discussion to see every reply.</p>{data.questions.filter(q=>q.author_id===user.id).map(q=><QuestionCard key={q.id} question={q} data={data}/>)}{data.answers.filter(a=>a.author_id===user.id).map(answer=><a className="profile-answer" href={`/questions/${data.questions.find(q=>q.id===answer.question_id)?.slug}?answer=${answer.id}#answer-${answer.id}`} key={answer.id}><span>Answer to</span><h3>{data.questions.find(q=>q.id===answer.question_id)?.title}</h3><p>{answer.body}</p><ProductNote answer={answer}/><strong>{answer.score} helpful score</strong></a>)}{!data.questions.length&&<Empty>No field contributions yet.</Empty>}<Pager data={data} setParam={setParam}/></div><aside className="profile-aside"><div className="xp-card"><span>Community contributions</span><strong>{user.xp}</strong><small>XP · {level(user.xp)}</small><p>XP reflects contributions and community feedback. It does not certify expertise.</p></div><div className="stat-grid"><div><strong>{user.answer_count}</strong><small>answers</small></div><div><strong>{user.best_count}</strong><small>accepted answers</small></div><div><strong>{user.likes}</strong><small>helpful votes</small></div><div><strong>{user.followers}</strong><small>followers</small></div><div><strong>{user.following}</strong><small>following</small></div></div></aside></section></>;
}
const myTabs:Record<string,string>={questions:"My questions",answers:"My answers",saved:"Saved",following:"Following",invitations:"Invitations",notifications:"Inbox",profile:"Edit profile",reports:"My reports"};
function MyCommunity({data,params,setParam,act,upload}:{data:Snapshot;params:URLSearchParams;setParam:(key:string,value:string)=>void;act:Act;upload:Upload}) {
  const user=data.users.find(u=>u.id===data.currentUserId);const tab=params.get("tab")||"questions";
  if(!user)return <Empty><h1>Your community</h1><p>Sign in to find your saved questions, invitations and updates.</p><a className="button primary" href="/auth?returnTo=%2Fme">Sign in</a></Empty>;
  return <section className="account-page"><div className="section-heading"><div><span className="kicker">My community</span><h1>Welcome, {user.name}</h1></div><div className="form-actions"><a href="/rewards?tab=wallet">My points &amp; rewards</a><a href={`/people/${user.handle}`}>View public profile</a><button onClick={async()=>{if(await act({action:"signOut"}))window.location.href="/";}}>Log out &amp; continue as guest</button></div></div>{data.isModerator&&<section className="admin-publishing"><div><span className="kicker">Admin workspace</span><h2>Share what you know.</h2><p>Write an article, update your knowledge library or review community activity.</p></div><div className="admin-publishing-actions"><a className="button primary" href="/ask?type=knowledge">Create an article <span aria-hidden="true">↗</span></a><div><a href="/search?type=knowledge">Knowledge library</a><a href="/moderation">Review queue</a></div></div></section>}{!data.config.local&&!data.emailVerified&&<div className="load-error"><p>Verify your email before posting. <a href="/me?tab=profile">Open account settings</a> to send a verification link.</p></div>}<nav className="account-tabs" aria-label="My community sections">{Object.entries(myTabs).map(([key,label])=><button key={key} aria-current={tab===key?"page":undefined} className={tab===key?"active":""} onClick={()=>setParam("tab",key)}>{label}</button>)}</nav>{tab==="profile"?<ProfileEditor key={user.id} user={user} data={data} act={act} upload={upload}/>:tab==="notifications"?<div className="notice-list">{data.notifications.map(n=><article className={!n.read_at?"unread":""} key={n.id}><a href={n.href}>{n.message}</a><small>{ago(n.created_at)}</small>{!n.read_at&&<button onClick={()=>act({action:"readNotice",id:n.id})}>Mark read</button>}</article>)}{!data.notifications.length&&<Empty>No updates yet. Follow questions to hear when new answers arrive.</Empty>}</div>:tab==="reports"?<div>{data.ownReports.map(r=><article className="review-card" key={r.id}><strong>{r.target_type} report · {r.status}</strong><p>{r.reason}</p><p>{r.resolution||"Waiting for review"}</p></article>)}{!data.ownReports.length&&<Empty>You have not submitted any reports.</Empty>}</div>:<>{tab==="following"&&<section className="following-people"><h2>Members you follow</h2>{data.users.filter(u=>data.userFollows.includes(u.id)).map(u=><UserBadge key={u.id} user={u}/>)}{!data.userFollows.length&&<p>Follow people from their public profiles.</p>}<h2>Questions you follow</h2></section>}{tab==="invitations"&&<section><h2>Invitations sent and received</h2>{data.invitations.map(i=><article className="invitation-card" key={i.id}><a href={`/questions/${i.slug}`}>{i.title}</a><p>{i.expert_id===user.id?"Invited to answer":"Invitation sent"} · {i.status}</p>{i.expert_id===user.id&&["pending","read"].includes(i.status)&&<div className="form-actions"><button onClick={()=>act({action:"invitationStatus",id:i.id,status:"read"})}>Mark read</button><button onClick={()=>act({action:"invitationStatus",id:i.id,status:"declined"})}>Decline</button></div>}</article>)}</section>}{tab==="answers"?<><p>Your recent answers in each discussion. Open a discussion to see every reply.</p>{data.answers.filter(a=>a.author_id===user.id).map(a=><a className="profile-answer" key={a.id} href={`/questions/${data.questions.find(q=>q.id===a.question_id)?.slug}?answer=${a.id}#answer-${a.id}`}><h3>{data.questions.find(q=>q.id===a.question_id)?.title}</h3><p>{a.body}</p><ProductNote answer={a}/></a>)}</>:tab!=="invitations"&&data.questions.map(q=><QuestionCard key={q.id} question={q} data={data}/>)}{!data.questions.length&&tab!=="invitations"&&<Empty>No questions here yet. <a href="/">Explore the community</a></Empty>}{tab==="invitations"&&!data.invitations.length&&<Empty>No invitations yet.</Empty>}<Pager data={data} setParam={setParam}/></>}</section>;
}
function Moderation({data,act}:{data:Snapshot;act:Act}) {
  if(!data.isModerator)return <Empty><h1>Reviewer access required</h1><p>This area is restricted to appointed community reviewers.</p><a href="/me">Back to my community</a></Empty>;
  return <section className="account-page"><span className="kicker">Community review</span><h1>Review queue</h1><p>Record a clear reason for every decision. Verification approval notes are public; never include private application details.</p><h2>Expert applications</h2>{data.applications.map(a=><article className="review-card" key={a.user_id}><h3>{data.users.find(u=>u.id===a.user_id)?.name || a.user_id} · {a.scope}</h3><p>Status: {a.status}</p><p className="preserve-lines">{a.evidence}</p>{["pending","approved"].includes(a.status)&&<Form className="inline-form" submit={async form=>Boolean(await act({action:"reviewExpert",userId:a.user_id,decision:form.get("decision"),reason:form.get("reason")}))}><label>Decision<select name="decision">{a.status==="pending"?<><option value="approved">Approve verification</option><option value="rejected">Request changes / reject</option></>:<option value="revoked">Revoke verification</option>}</select></label><label>Public verification basis / review reason<textarea name="reason" required minLength={10} maxLength={500}/></label><button className="button primary">Save decision</button></Form>}</article>)}{!data.applications.length&&<Empty>No expert applications.</Empty>}<h2>Content reports</h2>{data.reports.map(r=><article className="review-card" key={r.id}><h3>{r.target_type} #{r.target_id} · {r.status}</h3><blockquote>{r.content||"Content is unavailable"}</blockquote><p><strong>Report:</strong> {r.reason}</p><p>{r.resolution}</p><Form className="inline-form" submit={async form=>Boolean(await act({action:"moderate",reportId:r.id,decision:form.get("decision"),reason:form.get("reason")}))}><label>Decision<select name="decision"><option value="hide">Hide content</option><option value="restore">Restore content</option><option value="dismiss">Dismiss report</option></select></label><label>Reason<textarea name="reason" required minLength={4} maxLength={500}/></label><button className="button primary">Apply decision</button></Form></article>)}{!data.reports.length&&<Empty>No content reports.</Empty>}<details className="moderation-log"><summary>Review history</summary>{data.moderationLog.map(log=><p key={log.id}>{ago(log.created_at)} · {log.action} · {log.target_type} {log.target_id} · {log.reason}</p>)}</details></section>;
}
function Auth({data,act,params}:{data:Snapshot;act:Act;params:URLSearchParams}) {
  const [mode,setMode]=useState("signIn"); const returnTo=params.get("returnTo")||"/me";
  if(["forgot","reset","verify"].includes(params.get("mode")||""))return <AccountRecovery mode={params.get("mode")!} data={data} act={act}/>;
  if(data.currentUserId)return <Empty><h1>You are signed in</h1><a className="button primary" href="/me">My community</a></Empty>;
  return <section className="auth-page"><div className="auth-intro"><span className="kicker">Grounded membership</span><h1>Join the<br/><em>conversation.</em></h1><p>Ask local questions, save useful answers and share your field experience.</p></div><Form className="auth-card" submit={async form=>{const result=await act({...values(form),action:mode});if(result){window.location.href=returnTo.startsWith("/")&&!returnTo.startsWith("//")&&!returnTo.includes("\\")?returnTo:"/me";return true;}return false;}}><div className="auth-tabs"><button type="button" className={mode==="signIn"?"active":""} onClick={()=>setMode("signIn")}>Sign in</button>{data.config.registrationOpen&&<button type="button" className={mode==="signUp"?"active":""} onClick={()=>setMode("signUp")}>Create account</button>}</div>{!data.config.registrationOpen&&<p role="status">Registration is not open during this preview. Existing members can sign in.</p>}<h2>{mode==="signIn"?"Welcome back":"Your field profile"}</h2>{mode==="signUp"&&<label>Display name<input name="name" autoComplete="name" required minLength={2} maxLength={80}/></label>}<label>Email<input name="email" type="email" autoComplete="email" required maxLength={180}/></label><label>Password<input name="password" type="password" autoComplete={mode==="signIn"?"current-password":"new-password"} required minLength={mode==="signUp"?10:undefined} maxLength={128}/></label>{mode==="signUp"&&<div className="two-col"><label>State<select name="state" required defaultValue=""><option value="">Choose a state</option>{states.map(s=><option key={s}>{s}</option>)}</select></label><label>Nearest town<input name="town" required maxLength={80}/></label></div>}<Challenge siteKey={data.config.turnstileSiteKey} action={mode}/><button className="button primary auth-submit">{mode==="signIn"?"Sign in":"Create account"}</button>{data.config.emailEnabled&&<a href="/auth?mode=forgot">Forgot your password?</a>}<a className="guest-link" href="/">Continue as a guest</a></Form></section>;
}
function Leaderboard({data,params,setParam}:{data:Snapshot;params:URLSearchParams;setParam:(key:string,value:string)=>void}) {
  const people=data.users.filter(u=>data.peopleIds.includes(u.id)).sort((a,b)=>b.xp-a.xp);
  return <section className="leaderboard-page"><div className="section-heading"><div><span className="kicker">Knowledge shared</span><h1>Community contributors</h1><p>10 XP per answer, 2 per helpful vote and 20 for another member accepting your answer. Professional verification is separate.</p></div></div><div className="filters"><Select label="Field" name="category" items={categories} value={params.get("category")||""} onChange={v=>setParam("category",v)}/><Select label="Region" name="state" items={states} value={params.get("state")||""} onChange={v=>setParam("state",v)}/></div><div className="contributor-list">{people.map((user,i)=><a key={user.id} href={`/people/${user.handle}`}><span>{(data.page-1)*24+i+1}</span><Avatar user={user}/><div><strong>{user.name}</strong><small>{user.town}, {user.state} · {level(user.xp)}{user.demo?" · Demo profile":""}</small></div><b>{user.xp} XP</b></a>)}</div>{!people.length&&<Empty>No matching contributors yet.</Empty>}<Pager data={data} setParam={setParam}/></section>;
}
export default function Community({view,slug="",handle="",initialData=null,initialSearch=""}:{view:View;slug?:string;handle?:string;initialData?:Snapshot|null;initialSearch?:string}) {
  const [data,setData]=useState<Snapshot|null>(initialData),[error,setError]=useState(""),[toast,setToast]=useState(""),[search,setSearch]=useState(initialSearch?`?${initialSearch}`:"");
  const [needsAuth,setNeedsAuth]=useState(false);const activeSearch=useRef(search);activeSearch.current=search;
  const [ready,setReady]=useState(false);const version=useRef(0);
  useEffect(()=>{setSearch(window.location.search);setReady(true);const pop=()=>setSearch(window.location.search);window.addEventListener("popstate",pop);return()=>window.removeEventListener("popstate",pop);},[]);
  const load=useCallback(async()=>{const ownVersion=++version.current;const params=new URLSearchParams(activeSearch.current);params.set("view",view);if(slug)params.set("slug",slug);if(handle)params.set("handle",handle);try{const response=await fetch(`/api/community?${params}`,{cache:"no-store"});const result=await response.json() as Snapshot & {error?:string};if(!response.ok)throw new Error(result.error||"Could not load the community.");if(ownVersion===version.current){setData(result);setError("");if(result.currentUserId)setNeedsAuth(false);}}catch(cause){if(ownVersion===version.current)setError(cause instanceof Error?cause.message:"Could not load the community.");}},[view,slug,handle]);
  useEffect(()=>{if(ready)void load();},[ready,search,load]);
  useEffect(()=>{if(!toast)return;const timeout=window.setTimeout(()=>setToast(""),6000);return()=>window.clearTimeout(timeout);},[toast]);
  const setParam=(key:string,value:string)=>{const params=new URLSearchParams(search);if(value)params.set(key,value);else params.delete(key);if(key!=="page")params.delete("page");const next=params.toString()?`?${params}`:"";window.history.pushState(null,"",window.location.pathname+next);activeSearch.current=next;setSearch(next);};
  const act:Act=async body=>{try{const response=await fetch("/api/community",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const result=await response.json() as Record<string,unknown>;if(["signIn","signUp","requestReset"].includes(String(body.action)))window.dispatchEvent(new Event("grounded:auth-attempt"));if(!response.ok){if(response.status===401&&!['signIn','signUp'].includes(String(body.action))){setNeedsAuth(true);setToast("Please sign in in another tab, then retry. Your form stays here.");return null;}setToast(String(result.error||"Could not save. Your input has been kept."));return null;}setToast(result.message?String(result.message):body.action==="report"?"Report received. Track the outcome in My reports.":"Saved.");await load();return result;}catch{setToast("Connection interrupted. Your input has been kept. Please try again.");return null;}};
  const upload:Upload=async file=>{
    if(!data?.config.uploadsEnabled)throw new Error("Photo uploads are not enabled yet. You can still publish your text.");
    if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error("Choose a JPEG, PNG or WebP photo smaller than 5 MB.");
    // Decode and re-encode browser uploads to remove metadata before publishing.
    const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw new Error("Use a photo smaller than 40 megapixels.");}
    const canvas=document.createElement('canvas');const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();throw new Error("Photo processing is unavailable in this browser.");}ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
    const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("Could not process this photo.")),"image/webp",0.88));
    const form=new FormData();form.set("image",blob,"photo.webp");const response=await fetch("/api/upload",{method:"POST",body:form});const result=await response.json() as {error?:string;url:string};if(!response.ok)throw new Error(result.error||"Image upload failed. Your text has been kept.");return result.url;
  };
  const params=new URLSearchParams(search);
  return <><Header data={data}/>{data&&!data.config.registrationOpen&&<aside className="preview-banner" role="status">Preview · Explore Grounded Australia. New member registration opens after email setup is complete.</aside>}{toast&&<div className="toast" role="status">{toast}</div>}<main>{needsAuth&&<div className="load-error" role="alert"><p>Your form is still here. Sign in in another tab, then continue.</p><a className="button primary" href="/auth?returnTo=%2Fme" target="_blank" rel="noopener">Sign in in a new tab</a><button onClick={()=>void load()}>I have signed in</button></div>}{error&&<div className="load-error" role="alert"><p>{error}</p><button onClick={()=>void load()}>Retry loading</button></div>}{!data?<section className="loading"><p>{error?"The community is temporarily unavailable.":"Gathering field knowledge…"}</p></section>:view==="home"||view==="search"?<Feed data={data} params={params} setParam={setParam} search={view==="search"}/>:view==="ask"?<QuestionEditor data={data} act={act} upload={upload} knowledge={params.get("type")==="knowledge"}/>:view==="question"?<QuestionPage slug={slug} data={data} act={act} upload={upload}/>:view==="profile"?<Profile handle={handle} data={data} act={act} setParam={setParam}/>:view==="me"?<MyCommunity data={data} params={params} setParam={setParam} act={act} upload={upload}/>:view==="moderation"?<Moderation data={data} act={act}/>:view==="auth"?<Auth data={data} act={act} params={params}/>:view==="rewards"?<RewardsPanel tab={params.get("tab") || "catalogue"} onTabChange={value=>setParam("tab",value)}/>:<Leaderboard data={data} params={params} setParam={setParam}/>}</main><footer><a className="brand" href="/">Grounded Australia</a><p>Practical knowledge, rooted in place.</p><span>Local experience · Clear sources · Open discussion</span></footer></>;
}
